select md5(cast(repository as varchar) || '|' || cast(captured_at as varchar)) as observation_source_key,
       repository, captured_at, stars, forks, watchers, open_issues_and_prs
from {{ source('raw', 'observations') }}

select md5(cast(repository as varchar) || '|' || cast(asset_id as varchar) || '|' || cast(captured_at as varchar)) as release_asset_source_key,
       repository, release_id as event_id, asset_id, captured_at, download_count
from {{ source('raw', 'release_assets') }}

select md5(cast(repository as varchar) || '|' || cast(signal as varchar)) as signal_capture_source_key,
       repository, signal, captured_at, complete
from {{ source('raw', 'signal_captures') }}

select md5(cast(repository as varchar) || '|' || cast(date as varchar)) as stargazer_day_source_key,
       repository, date, stars
from {{ source('raw', 'stargazer_days') }}

select md5(cast(repository as varchar) || '|' || cast(date as varchar)) as fork_day_source_key,
       repository, date, forks
from {{ source('raw', 'fork_days') }}

select md5(cast(repository as varchar) || '|' || cast(number as varchar)) as issue_source_key,
       repository, number, kind, created_at, closed_at, merged_at, author_association
from {{ source('raw', 'issues') }}

select md5(cast(repository as varchar) || '|' || registry || '|' || package || '|' || cast(date as varchar)) as package_download_source_key,
       repository, registry, package, date, downloads
from {{ source('raw', 'package_downloads') }}
